'use client';

import { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import * as Dialog from '@radix-ui/react-dialog';
import { AnimatePresence, motion } from 'framer-motion';
import { ArrowDownLeft, ArrowLeft, ArrowUpLeft, BadgeCheck, BookOpen, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Download, Eye, FileBox, FileCheck2, Gem, Heart, Home, Instagram, Layers3, LockKeyhole, Mail, MapPin, Menu, MessageCircle, Minus, Package, Pause, Play, Plus, Search, ShieldCheck, ShoppingBag, SlidersHorizontal, Sparkles, Trash2, UploadCloud, UserRound, WandSparkles, X } from 'lucide-react';
import { articles, courses, faNumber, money, products, tiers } from '@/lib/data';

type Product = typeof products[number];
type Course = typeof courses[number];
const nav = [
  { href: '/courses', label: 'دوره‌ها و پکیج‌ها' }, { href: '/marketplace', label: 'مارکت‌پلیس فایل STL' },
  { href: '/orders', label: 'سفارش طراحی' }, { href: '/journal', label: 'مقالات و اخبار' },
  { href: '/about', label: 'درباره ما' }, { href: '/contact', label: 'تماس با ما' }
];
const dock = [{ href: '/', label: 'خانه', icon: Home }, { href: '/courses', label: 'پکیج‌ها', icon: BookOpen }, { href: '/marketplace', label: 'مارکت‌پلیس', icon: Gem }, { href: '/challenges', label: 'چالش‌ها', icon: Layers3 }, { href: '/profile', label: 'حساب من', icon: UserRound }];

function Brand() { return <Link href="/" className="brand" aria-label="یاسین گلد آرت، صفحه اصلی"><span className="brand-mark"><Gem size={22} strokeWidth={1.4}/></span><span className="brand-text"><strong>YASIN GOLD ART</strong><small>آکادمی و آتلیه طراحی جواهر</small></span><BadgeCheck size={16} className="brand-verified"/></Link>; }
function SectionHead({ eyebrow, title, desc, light = false, action }: { eyebrow: string; title: React.ReactNode; desc?: string; light?: boolean; action?: React.ReactNode }) { return <div className={`section-head ${light ? 'section-head-light' : ''}`}><div><span className="eyebrow"><span className="eyebrow-line"/>{eyebrow}</span><h2>{title}</h2>{desc && <p>{desc}</p>}</div>{action}</div>; }
function ButtonLink({ href, children, outline = false }: { href: string; children: React.ReactNode; outline?: boolean }) { return <Link href={href} className={outline ? 'btn btn-outline' : 'btn btn-gold'}>{children}<ArrowUpLeft size={17}/></Link>; }
function JewelryVisual({ variant = 'ring', large = false }: { variant?: string; large?: boolean }) { return <div className={`jewelry-visual visual-${variant} ${large ? 'visual-large' : ''}`}><div className="visual-glow"/><div className="jewel-orbit orbit-one"/><div className="jewel-orbit orbit-two"/><div className="jewel-piece"><span className="jewel-stone"/><span className="jewel-band"/></div><span className="visual-spark">✦</span></div>; }
function Fade({ children, className = '' }: { children: React.ReactNode; className?: string }) { return <motion.div className={className} initial={{ opacity: 0, y: 25 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: .15 }} transition={{ duration: .55 }}>{children}</motion.div>; }

export default function App({ section = 'home' }: { section?: string }) {
  const [cart, setCart] = useState<string[]>([]);
  const [purchased, setPurchased] = useState<string[]>([]);
  const [user, setUser] = useState<string | null>(null);
  const [cartOpen, setCartOpen] = useState(false);
  const [authOpen, setAuthOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [preview, setPreview] = useState<Product | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [profileMenu, setProfileMenu] = useState(false);
  const [toast, setToast] = useState('');
  useEffect(() => { try { setCart(JSON.parse(localStorage.getItem('yga-cart') || '[]')); setPurchased(JSON.parse(localStorage.getItem('yga-purchased') || '[]')); setUser(localStorage.getItem('yga-user')); } catch {} }, []);
  useEffect(() => { if ('serviceWorker' in navigator && process.env.NODE_ENV === 'production') navigator.serviceWorker.register('/yasin-gold-art/sw.js', { scope: '/yasin-gold-art/' }).catch(() => {}); }, []);
  useEffect(() => { localStorage.setItem('yga-cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('yga-purchased', JSON.stringify(purchased)); }, [purchased]);
  useEffect(() => { if (user) localStorage.setItem('yga-user', user); else localStorage.removeItem('yga-user'); }, [user]);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(''), 3200); return () => clearTimeout(t); }, [toast]);
  const addCart = (id: string) => { setCart(v => [...v, id]); setToast('فایل به سبد خرید اضافه شد'); };
  const removeCart = (index: number) => setCart(v => v.filter((_, i) => i !== index));
  const openAuth = () => setAuthOpen(true);
  return <>
    <div className="site-shell">
      <div className="announcement"><span>✦</span> مسیر حرفه‌ای طراحی جواهر، از اولین اسکچ تا استانداردهای تولید <Link href="/courses">کاوش دوره‌ها <ArrowLeft size={13}/></Link></div>
      <header className="header"><div className="container header-inner"><Brand/><nav className="desktop-nav">{nav.map(item => <Link className={section === item.href.slice(1) ? 'active' : ''} href={item.href} key={item.href}>{item.label}</Link>)}</nav><div className="header-actions"><button aria-label="جستجو" className="icon-btn" onClick={() => setSearchOpen(true)}><Search size={20}/></button><button aria-label="سبد خرید" className="icon-btn cart-trigger" onClick={() => setCartOpen(true)}><ShoppingBag size={20}/>{cart.length > 0 && <i>{faNumber(cart.length)}</i>}</button><span className="header-divider"/><div className="profile-trigger"><button className="login-button" onClick={user ? () => setProfileMenu(!profileMenu) : openAuth}>{user ? <><UserRound size={17}/>{user}<ChevronDown size={14}/></> : <>ورود / ثبت‌نام <ArrowUpLeft size={16}/></>}</button>{user && profileMenu && <div className="profile-dropdown"><Link href="/profile" onClick={() => setProfileMenu(false)}>حساب من <UserRound size={15}/></Link><button onClick={() => { setUser(null); setProfileMenu(false); }}>خروج از حساب <ArrowLeft size={15}/></button></div>}</div><button className="mobile-menu-btn icon-btn" aria-label="منو" onClick={() => setMenuOpen(!menuOpen)}>{menuOpen ? <X/> : <Menu/>}</button></div></div>{menuOpen && <nav className="mobile-menu">{nav.map(n => <Link href={n.href} key={n.href} onClick={() => setMenuOpen(false)}>{n.label}<ChevronLeft size={16}/></Link>)}</nav>}</header>
      <main>{section === 'journal' && <ReaderProgress/>}{section === 'home' ? <HomePage onPreview={setPreview} onAdd={addCart} onAuth={openAuth}/> : section === 'courses' ? <CoursesPage onAuth={openAuth}/> : section === 'marketplace' ? <MarketplacePage onPreview={setPreview} onAdd={addCart}/> : section === 'orders' ? <OrdersPage onToast={setToast}/> : section === 'journal' ? <JournalPage/> : section === 'about' ? <AboutPage/> : section === 'contact' ? <ContactPage onToast={setToast}/> : section === 'challenges' ? <ChallengesPage onAuth={openAuth}/> : section === 'profile' ? <ProfilePage user={user} cartCount={cart.length} purchased={purchased} onAuth={openAuth} onLogout={() => setUser(null)}/> : section === 'auth' ? <AuthPage onLogin={name => { localStorage.setItem('yga-user', name); setUser(name); window.location.href = '/profile'; }}/> : <HomePage onPreview={setPreview} onAdd={addCart} onAuth={openAuth}/>}</main>
      <Footer/>
      <nav className="mobile-dock" aria-label="ناوبری موبایل">{dock.map(item => { const Icon = item.icon; return <Link href={item.href} className={section === item.href.slice(1) || (section === 'home' && item.href === '/') ? 'selected' : ''} key={item.href}><Icon size={21} strokeWidth={1.8}/><span>{item.label}</span></Link>; })}</nav>
    </div>
    <Dialog.Root open={authOpen} onOpenChange={setAuthOpen}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="dialog-content auth-dialog"><Dialog.Title className="sr-only">ورود و ثبت‌نام</Dialog.Title><Dialog.Close className="dialog-close" aria-label="بستن"><X size={19}/></Dialog.Close><AuthForm onLogin={name => { setUser(name); setAuthOpen(false); setToast('به یاسین گلد آرت خوش آمدید'); }}/></Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={searchOpen} onOpenChange={setSearchOpen}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="dialog-content search-dialog"><Dialog.Title className="sr-only">جستجو</Dialog.Title><Dialog.Close className="dialog-close" aria-label="بستن"><X size={19}/></Dialog.Close><SearchPanel close={() => setSearchOpen(false)}/></Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={!!preview} onOpenChange={v => !v && setPreview(null)}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="dialog-content preview-dialog"><Dialog.Title className="sr-only">پیش‌نمایش فایل</Dialog.Title><Dialog.Close className="dialog-close" aria-label="بستن"><X size={19}/></Dialog.Close>{preview && <PreviewPanel product={preview} onAdd={() => { addCart(preview.id); setPreview(null); }}/>}</Dialog.Content></Dialog.Portal></Dialog.Root>
    <Dialog.Root open={cartOpen} onOpenChange={setCartOpen}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="cart-drawer"><Dialog.Title className="drawer-title">سبد خرید <span>{faNumber(cart.length)} محصول</span></Dialog.Title><Dialog.Close className="dialog-close" aria-label="بستن"><X size={20}/></Dialog.Close>{cart.length ? <><div className="cart-items">{cart.map((id, i) => { const p = products.find(x => x.id === id); return p && <div className="cart-item" key={`${id}-${i}`}><JewelryVisual variant={p.image}/><div><b>{p.title}</b><small>{p.format.join(' / ')}</small><strong>{money(p.price)}</strong></div><button aria-label={`حذف ${p.title}`} onClick={() => removeCart(i)}><Trash2 size={17}/></button></div>; })}</div><div className="cart-footer"><div><span>جمع کل</span><strong>{money(cart.reduce((sum, id) => sum + (products.find(p => p.id === id)?.price || 0), 0))}</strong></div><button className="btn btn-gold full" onClick={() => { setCartOpen(false); if (!user) setAuthOpen(true); else { setPurchased(v => [...new Set([...v, ...cart])]); setCart([]); setToast('خرید نمایشی ثبت شد؛ نمونه فایل در حساب شماست'); } }}>تکمیل خرید نمایشی <ArrowLeft size={17}/></button><p>پرداخت واقعی انجام نمی‌شود. فایل دریافتی فقط نمونه غیرتولیدی است.</p></div></> : <div className="empty-cart"><ShoppingBag size={42}/><h3>سبد خرید شما خالی است</h3><p>فایل‌های صنعتی منتخب را در مارکت‌پلیس کشف کنید.</p><Dialog.Close asChild><Link href="/marketplace" className="btn btn-gold">مشاهده فایل‌ها <ArrowUpLeft size={17}/></Link></Dialog.Close></div>}</Dialog.Content></Dialog.Portal></Dialog.Root>
    <AnimatePresence>{toast && <motion.div className="toast" initial={{ opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 24 }}><Check size={18}/>{toast}</motion.div>}</AnimatePresence>
  </>;
}

function HomePage({ onPreview, onAdd, onAuth }: { onPreview: (p: Product) => void; onAdd: (id: string) => void; onAuth: () => void }) {
  const [assetIndex, setAssetIndex] = useState(0);
  const [wireframe, setWireframe] = useState(false);
  const [tier, setTier] = useState('gold');
  const featured = products.slice(0, 3);
  return <>
    <section className="hero"><div className="hero-art"/><div className="hero-grid"/><div className="container hero-inner"><div className="hero-copy"><div className="hero-kicker"><span className="kicker-icon">✦</span> آکادمی تخصصی و آتلیه طراحی جواهر <span className="kicker-rule"/></div><h1>مرجع تخصصی طراحی سه‌بعدی<br/><em>طلا و جواهر؛</em><br/><span>از ایده تا ریخته‌گری صنعتی</span></h1><p>از یادگیری تا همکاری با کارگاه‌های ریخته‌گری و ساخت؛ مهارت طراحی صنعتی را به فرصت‌های حرفه‌ای و پروژه‌های بین‌المللی پیوند دهید.</p><div className="hero-actions"><ButtonLink href="/courses">شروع یادگیری و ورود به بازار</ButtonLink><ButtonLink href="/marketplace" outline>دانلود فایل‌های آماده صنعتی</ButtonLink></div><div className="hero-metrics"><div><strong>۵۰۰<span>+</span></strong><small>طرح صنعتی تایید شده</small></div><span className="metric-divider"/><div><strong>۱۰۰<span>٪</span></strong><small>همسو با استانداردهای تولید</small></div><span className="metric-divider"/><div><strong>۰۱</strong><small>مسیر، از یادگیری تا کارگاه</small></div></div></div><div className="hero-side-label"><span>ATELIER • ACADEMY • MARKETPLACE</span><i/></div></div><div className="hero-bottom"><span>SCROLL TO EXPLORE</span><ArrowDownLeft size={16}/></div></section>
    <div className="trust-strip"><div className="container trust-inner"><span>از ایده تا اجرای صنعتی</span><i/><span>آموزش چالش‌محور</span><i/><span>فایل‌های آماده تولید</span><i/><span>منتورشیپ تخصصی</span></div></div>
    <section className="section light-section pathways"><div className="container"><SectionHead eyebrow="THE YASIN WAY / مسیرهای شما" title={<>هر نقطه‌ای از مسیر که هستید،<br/><em>از همین‌جا شروع کنید.</em></>} desc="سه مسیر برای تبدیل ایده به مهارت، محصول و فرصت حرفه‌ای."/><div className="path-grid"><Fade className="path-card"><span className="path-index">۰۱ / LEARN</span><div className="path-icon"><BookOpen size={27}/></div><h3>یاد بگیرید</h3><p>از مبانی راینو تا مدل‌سازی پیشرفته و آماده‌سازی فایل برای تولید واقعی.</p><Link href="/courses">کاوش دوره‌ها <ArrowUpLeft size={17}/></Link></Fade><Fade className="path-card featured-path"><span className="path-index">۰۲ / CREATE</span><div className="path-icon"><Gem size={27}/></div><h3>فایل آماده تهیه کنید</h3><p>کتابخانه‌ای از مدل‌های سه‌بعدی دقیق برای سرعت بخشیدن به فرایند ساخت.</p><Link href="/marketplace">ورود به مارکت‌پلیس <ArrowUpLeft size={17}/></Link></Fade><Fade className="path-card"><span className="path-index">۰۳ / COLLABORATE</span><div className="path-icon"><WandSparkles size={27}/></div><h3>سفارش دهید</h3><p>ایده یا اسکچ خود را با تیم آتلیه به طرحی اختصاصی و قابل ساخت تبدیل کنید.</p><Link href="/orders">ثبت سفارش طراحی <ArrowUpLeft size={17}/></Link></Fade></div></div></section>
    <section className="section asset-section"><div className="container asset-layout"><div className="asset-copy"><SectionHead eyebrow="DIGITAL CRAFT / هنر دیجیتال" title={<>پشت هر فرم زیبا،<br/><em>یک منطق دقیق است.</em></>} desc="فایل‌هایی که برای نمایش ساخته نشده‌اند؛ برای ساختن طراحی شده‌اند." light/><p className="asset-extra">از فرم اولیه تا بررسی ضخامت، جای‌گذاری نگین و خروجی نهایی، هر جزئیات در مسیر تولید معنا پیدا می‌کند.</p><div className="asset-controls"><button onClick={() => setAssetIndex((assetIndex + featured.length - 1) % featured.length)} aria-label="طرح قبلی"><ChevronRight/></button><button onClick={() => setAssetIndex((assetIndex + 1) % featured.length)} aria-label="طرح بعدی"><ChevronLeft/></button><span>{faNumber(assetIndex + 1).padStart(2, '۰')} / ۰۳</span></div></div><div className="asset-display"><div className="asset-top"><span><span className="online-dot"/> پیش‌نمایش مدل سه‌بعدی</span><button className="view-switch" onClick={() => setWireframe(!wireframe)}><Eye size={15}/>{wireframe ? 'نمای رندر' : 'نمای وایرفریم'}</button></div><div className={`asset-stage ${wireframe ? 'wireframe' : ''}`}><JewelryVisual variant={featured[assetIndex].image} large/><div className="stage-grid"/><span className="stage-coordinate">X ۰.۰۰ &nbsp; Y ۰.۰۰ &nbsp; Z ۰.۰۰</span></div><div className="asset-caption"><div><small>{featured[assetIndex].en}</small><strong>{featured[assetIndex].title}</strong></div><button onClick={() => onPreview(featured[assetIndex])}>مشخصات فایل <ArrowUpLeft size={17}/></button></div></div></div></section>
    <section className="section light-section course-section"><div className="container"><SectionHead eyebrow="MASTER YOUR CRAFT / آموزش تخصصی" title={<>از اولین خط تا <em>امضای شما</em></>} desc="یادگیری را با چالش‌های واقعی کارگاه، پروژه عملی و بازخورد حرفه‌ای تجربه کنید." action={<Link className="text-link" href="/courses">مشاهده همه دوره‌ها <ArrowUpLeft size={18}/></Link>}/><div className="course-grid home-course-grid">{courses.slice(0,3).map((c,i) => <CourseCard key={c.id} course={c} index={i}/>)}</div></div></section>
    <section className="section pricing-section"><div className="container"><SectionHead eyebrow="CHOOSE YOUR PATH / سرمایه‌گذاری روی مهارت" title={<>یک مسیر برای هر <em>جاه‌طلبی.</em></>} desc="پکیج مناسب هدف و سطح تجربه خود را انتخاب کنید." light/><div className="pricing-grid">{tiers.map(t => <div className={`pricing-card ${t.id === tier ? 'selected' : ''} ${t.id === 'gold' ? 'popular' : ''}`} key={t.id} onClick={() => setTier(t.id)}><div className="price-card-top">{t.id === 'gold' && <span className="popular-badge">انتخاب اصلی</span>}{t.id === 'platinum' && <span className="vip-badge">VIP طراح ارشد</span>}<span className="tier-glyph">{t.icon}</span><small>{t.en} PACKAGE</small><h3>{t.name}</h3><p>{t.subtitle}</p></div><div className="tier-price"><strong>{t.price}</strong><span>{t.cadence}</span></div><ul>{t.features.map(f => <li key={f}><Check size={16}/>{f}</li>)}</ul><button className={`btn ${tier === t.id ? 'btn-gold' : 'btn-outline'} full`} onClick={e => { e.stopPropagation(); setTier(t.id); onAuth(); }}>انتخاب این مسیر <ArrowUpLeft size={17}/></button></div>)}</div><p className="pricing-note"><ShieldCheck size={17}/> دسترسی آموزشی مادام‌العمر است. قیمت‌ها و شرایط این نسخه، نمونه نمایشی هستند.</p></div></section>
    <section className="section moat-section light-section"><div className="container moat-layout"><div><SectionHead eyebrow="BEYOND THE CLASSROOM / فراتر از کلاس" title={<>آموزش وقتی ارزشمند است<br/>که <em>قابل ساخت باشد.</em></>} desc="فاصله میان یک مدل زیبا و یک قطعه قابل تولید را با تمرین و استاندارد پر می‌کنیم."/><Link href="/about" className="text-link">با متد ما آشنا شوید <ArrowUpLeft size={18}/></Link></div><div className="compare-card"><div className="compare-head"><span>دوره‌های تئوری سنتی</span><strong>متد چالش‌محور یاسین گلد آرت</strong></div>{[['تمرکز بر ابزار و فرمان‌ها','تمرکز بر مسئله واقعی تولید'],['تمرین‌های بدون بازخورد','بازخورد تخصصی مرحله به مرحله'],['خروجی صرفاً نمایشی','فایل قابل چاپ و ریخته‌گری'],['پایان مسیر در کلاس','اتصال مهارت به فرصت کارگاهی']].map((row,i) => <div className="compare-row" key={i}><span><Minus size={15}/>{row[0]}</span><strong><Check size={15}/>{row[1]}</strong></div>)}</div></div></section>
    <section className="section market-section"><div className="container"><SectionHead eyebrow="CURATED CAD FILES / مارکت‌پلیس" title={<>جزئیاتی آماده برای <em>خلق کردن.</em></>} desc="مدل‌های پایه دقیق، قابل ویرایش و آماده برای ادامه داستان طراحی شما." light action={<Link className="text-link light-link" href="/marketplace">مشاهده همه فایل‌ها <ArrowUpLeft size={18}/></Link>}/><div className="product-grid home-product-grid">{products.slice(0,4).map(p => <ProductCard product={p} key={p.id} onPreview={onPreview} onAdd={onAdd}/>)}</div></div></section>
    <section className="section journal-preview light-section"><div className="container"><SectionHead eyebrow="THE JOURNAL / مجله تخصصی" title={<>دانشِ پشت <em>درخشش.</em></>} desc="از تکنولوژی طراحی تا ظرافت‌های تولید؛ یادداشت‌هایی برای طراحان کنجکاو." action={<Link className="text-link" href="/journal">همه مقالات <ArrowUpLeft size={18}/></Link>}/><div className="article-grid">{articles.slice(0,3).map(a => <ArticleCard key={a.id} article={a}/>)}</div></div></section>
    <section className="social-section"><div className="container"><SectionHead eyebrow="A SHARED CRAFT / شبکه همکاری" title={<>مهارت، در کنار <em>سازندگان</em> معنا می‌گیرد.</>} desc="فضایی برای پیوند طراحان، هنرجویان و کارگاه‌های تولیدی."/><div className="partner-logos" aria-label="حوزه‌های همکاری"><span><Gem size={23}/> آتلیه‌های طراحی</span><span><Layers3 size={23}/> کارگاه‌های ریخته‌گری</span><span><Sparkles size={23}/> سازندگان جواهر</span><span><FileBox size={23}/> خدمات چاپ سه‌بعدی</span></div><div className="testimonial-row"><div><span>✦ یادداشت نمونه هنرجو</span><p>«وقتی مدل را با نگاه کارگاه بررسی کردم، تازه فهمیدم چرا جزئیات کوچک در فایل نهایی مهم‌اند.»</p><small>روایت نمایشی برای معرفی تجربه یادگیری</small></div><div><span>✦ یادداشت نمونه سازنده</span><p>«هماهنگی طراح و سازنده از همان فایل سه‌بعدی شروع می‌شود؛ یک خروجی شفاف، مسیر تولید را ساده‌تر می‌کند.»</p><small>روایت نمایشی برای معرفی همکاری کارگاهی</small></div></div></div></section>
    <section className="closing-cta"><div className="container closing-inner"><span className="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h2>ایده‌های بزرگ، از یک <em>قدم</em> آغاز می‌شوند.</h2><p>مسیر خودتان را در دنیای طراحی و ساخت جواهر پیدا کنید.</p><div><ButtonLink href="/courses">مسیر یادگیری من</ButtonLink><ButtonLink href="/orders" outline>مشاوره سفارش اختصاصی</ButtonLink></div></div></section>
  </>;
}

function PageHero({ eyebrow, title, desc, icon }: { eyebrow: string; title: React.ReactNode; desc: string; icon?: React.ReactNode }) { return <section className="page-hero"><div className="container page-hero-inner"><div><span className="eyebrow"><span className="eyebrow-line"/>{eyebrow}</span><h1>{title}</h1><p>{desc}</p></div><div className="page-hero-symbol">{icon || <Gem size={100} strokeWidth={.5}/>}</div></div></section>; }
function CourseCard({ course, index }: { course: Course; index: number }) { return <Link href={`/courses?course=${course.id}`} className="course-card"><div className={`course-image image-${course.image}`}><JewelryVisual variant={course.image}/><span className="course-count">۰{faNumber(index + 1)} / COURSE</span><span className="course-level">{course.level}</span></div><div className="course-body"><span className="card-overline">{course.software} • {course.duration}</span><h3>{course.title}</h3><p>{course.description}</p><div className="course-meta"><span><Play size={14}/>{course.lessons}</span><span>مشاهده دوره <ArrowUpLeft size={17}/></span></div></div></Link>; }
function ProductCard({ product, onPreview, onAdd }: { product: Product; onPreview: (p: Product) => void; onAdd: (id: string) => void }) { return <div className="product-card"><div className={`product-image image-${product.image}`}><JewelryVisual variant={product.image}/>{product.badge && <span className="product-badge">{product.badge}</span>}<button className="quick-view" onClick={() => onPreview(product)} aria-label={`پیش‌نمایش ${product.title}`}><Eye size={18}/></button></div><div className="product-body"><small>{product.en}</small><h3>{product.title}</h3><div className="format-list">{product.format.map(f => <span key={f}>.{f}</span>)}</div><div className="product-mini-spec"><span>وزن ۷۵۰: {product.weight}</span><span>نگین: {product.stones}</span><span>تغییر سایز: {product.resize}</span></div><div className="product-footer"><strong>{money(product.price)}</strong><button onClick={() => onAdd(product.id)} aria-label={`افزودن ${product.title} به سبد خرید`}><Plus size={20}/></button></div></div></div>; }
function ArticleCard({ article }: { article: typeof articles[number] }) { return <Link href={`/journal?article=${article.id}`} className="article-card"><div className={`article-image image-${article.image}`}><JewelryVisual variant={article.image}/><span>{article.category}</span></div><div className="article-body"><div><span>{article.date}</span><span><Clock3 size={13}/>{article.read}</span></div><h3>{article.title}</h3><p>{article.excerpt}</p><span className="article-more">مطالعه مقاله <ArrowUpLeft size={17}/></span></div></Link>; }

function CoursesPage({ onAuth }: { onAuth: () => void }) {
  const [level, setLevel] = useState('همه'); const [software, setSoftware] = useState('همه'); const [chapter, setChapter] = useState(0); const [unlockedStage, setUnlockedStage] = useState(0); const [playing, setPlaying] = useState(false); const [support, setSupport] = useState(false);
  const [chosen, setChosen] = useState<string | null>(null);
  useEffect(() => { setChosen(new URLSearchParams(window.location.search).get('course')); }, []);
  const course = courses.find(c => c.id === chosen);
  const shown = courses.filter(c => (level === 'همه' || c.level === level) && (software === 'همه' || c.software === software));
  return <><PageHero eyebrow="ACADEMY / آکادمی" title={<>هنر را بیاموزید.<br/><em>صنعت را فتح کنید.</em></>} desc="دوره‌هایی با تمرکز بر مهارت عملی، استاندارد تولید و رشد حرفه‌ای در طراحی طلا و جواهر." icon={<BookOpen size={100} strokeWidth={.5}/>}/><div className="container content-section">{course ? <><button className="back-link" onClick={() => { setChosen(null); window.history.replaceState({}, '', '/courses'); }}><ChevronRight size={17}/> بازگشت به دوره‌ها</button><div className="detail-layout"><div><span className="eyebrow">COURSE DETAIL / جزئیات دوره</span><h2 className="detail-title">{course.title}</h2><p className="detail-intro">{course.description} این مسیر با تمرین‌های مرحله‌ای و بازخورد تخصصی، شما را برای خروجی قابل تولید آماده می‌کند.</p><div className="video-mock"><JewelryVisual variant={course.image} large/><div className="video-watermark">YASIN GOLD ART • PREVIEW</div><button className="play-btn" onClick={() => setPlaying(!playing)} aria-label={playing ? 'توقف پیش‌نمایش' : 'پخش پیش‌نمایش'}>{playing ? <Pause size={26} fill="currentColor"/> : <Play size={27} fill="currentColor"/>}</button><span className="video-caption">{playing ? 'در حال پخش پیش‌نمایش نمایشی' : 'پیش‌نمایش دوره'} • ۰۲:۳۰</span></div><div className="detail-block"><h3>نقشه راه یادگیری</h3><p>فصل‌ها با پیشرفت شما گام به گام در دسترس قرار می‌گیرند.</p><div className="syllabus">{['آشنایی با محیط و منطق طراحی','فرم‌سازی و مدل‌سازی پایه','طراحی جایگاه نگین و مخراجی','کنترل ضخامت و وزن قطعه','آماده‌سازی خروجی صنعتی'].map((name,i) => <button className={chapter === i ? 'open' : ''} key={name} onClick={() => i <= unlockedStage && setChapter(i)} disabled={i > unlockedStage}><span className="syllabus-num">۰{faNumber(i+1)}</span><span><b>{name}</b><small>{i <= unlockedStage ? 'در دسترس' : 'پس از تکمیل مرحله قبل'}</small></span>{i <= unlockedStage ? <Play size={17}/> : <LockKeyhole size={17}/>}</button>)}</div><button className="unlock-next" onClick={() => { setUnlockedStage(Math.min(4, unlockedStage + 1)); setChapter(Math.min(4, unlockedStage + 1)); }}>{unlockedStage >= 4 ? '' : `تکمیل مرحله و باز شدن فصل ${faNumber(unlockedStage + 2)} ←`}</button></div><div className="detail-block"><h3>چک‌لیست صنعتی این مسیر</h3><div className="check-grid">{['حداقل ضخامت دیواره قابل ریخته‌گری','مهار اصولی چنگ‌ها و جای‌گذاری نگین','برآورد وزن بر مبنای طلای ۱۸ عیار','کنترل مش و فایل نهایی چاپ سه‌بعدی'].map(t => <span key={t}><Check size={16}/>{t}</span>)}</div></div></div><aside className="detail-aside"><div className="enroll-card"><span className="eyebrow">START CREATING</span><h3>آماده‌اید شروع کنید؟</h3><div className="enroll-price">{course.price} <span>تومان</span></div><p>دسترسی مادام‌العمر به محتوای دوره</p><button className="btn btn-gold full" onClick={onAuth}>ثبت‌نام در دوره <ArrowUpLeft size={17}/></button><div className="enroll-facts"><span><Clock3 size={16}/>{course.duration} آموزش</span><span><Play size={16}/>{course.lessons} ویدئو</span><span><ShieldCheck size={16}/>تمرین و بازخورد تخصصی</span></div></div><div className="addon-card"><span><Sparkles size={20}/> مکمل مسیر شما</span><h4>تمدید پشتیبانی و منتورشیپ</h4><p>یک ماه همراهی بیشتر برای حل تمرین و بررسی پروژه‌های شما.</p><button onClick={() => setSupport(!support)}>{support ? 'به درخواست شما اضافه شد ✓' : 'افزودن ۱ ماه پشتیبانی +'}</button></div></aside></div></> : <><div className="filter-header"><div><span className="eyebrow">EXPLORE COURSES</span><h2>دوره‌های تخصصی</h2></div><span>{faNumber(shown.length)} دوره یافت شد</span></div><div className="filter-bar"><SlidersHorizontal size={18}/><span>فیلتر بر اساس:</span><div className="chip-group">{['همه','مقدماتی','پیشرفته','منتورشیپ ارشد'].map(x => <button className={level === x ? 'on' : ''} onClick={() => setLevel(x)} key={x}>{x}</button>)}</div><select value={software} onChange={e => setSoftware(e.target.value)} aria-label="نرم‌افزار"><option>همه</option><option>MatrixGold</option><option>Rhino</option><option>ZBrush</option></select></div><div className="course-grid">{shown.map((c,i) => <div onClick={() => { setChosen(c.id); window.history.replaceState({}, '', `/courses?course=${c.id}`); window.scrollTo(0,0); }} key={c.id} className="course-click"><CourseCard course={c} index={i}/></div>)}</div>{shown.length === 0 && <EmptyState/>}</>}</div></>;
}

function MarketplacePage({ onPreview, onAdd }: { onPreview: (p: Product) => void; onAdd: (id: string) => void }) { const [category, setCategory] = useState('همه'); const [format, setFormat] = useState('همه'); const [query, setQuery] = useState(''); const filtered = products.filter(p => (category === 'همه' || p.category === category) && (format === 'همه' || p.format.includes(format)) && p.title.includes(query)); return <><PageHero eyebrow="THE CAD MARKETPLACE / مارکت‌پلیس" title={<>فایل‌های دقیق.<br/><em>ایده‌های بی‌پایان.</em></>} desc="مدل‌های پایه و فایل‌های سه‌بعدی آماده ویرایش، چاپ و ادامه طراحی صنعتی." icon={<FileBox size={100} strokeWidth={.5}/>}/><div className="container content-section"><div className="filter-header"><div><span className="eyebrow">CURATED ASSETS</span><h2>کتابخانه فایل‌های سه‌بعدی</h2></div><span>{faNumber(filtered.length)} فایل یافت شد</span></div><div className="market-tools"><label className="market-search"><Search size={18}/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="جستجو در فایل‌ها..."/></label><div className="chip-group">{['همه','انگشتر','مخراجی','قالب آماده','مدال'].map(x => <button className={category === x ? 'on' : ''} onClick={() => setCategory(x)} key={x}>{x}</button>)}</div><select value={format} onChange={e => setFormat(e.target.value)} aria-label="فرمت فایل"><option value="همه">همه فرمت‌ها</option><option value="3DM">.3DM</option><option value="STL">.STL</option><option value="OBJ">.OBJ</option></select></div><div className="product-grid">{filtered.map(p => <ProductCard product={p} key={p.id} onPreview={onPreview} onAdd={onAdd}/>)}</div>{!filtered.length && <EmptyState/>}<div className="market-promise"><span><FileCheck2/> فایل‌های بررسی شده</span><span><Download/> دسترسی دانلود پس از خرید</span><span><ShieldCheck/> مشخصات فنی شفاف</span></div></div></>; }

function OrdersPage({ onToast }: { onToast: (s: string) => void }) { const [step, setStep] = useState(1); const [category, setCategory] = useState('انگشتر تک‌نگین'); const [fileName, setFileName] = useState(''); const [weight, setWeight] = useState(''); const [setting, setSetting] = useState('چنگی'); const [quantity, setQuantity] = useState('تک‌سازی'); const [name, setName] = useState(''); const [phone, setPhone] = useState(''); const [agree, setAgree] = useState(false); const [done, setDone] = useState(false); const submit = () => { if (!name.trim() || !/^09\d{9}$/.test(phone.replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))))) { onToast('نام و شماره موبایل معتبر وارد کنید'); return; } if (!agree) { onToast('لطفاً شرایط محرمانگی را تایید کنید'); return; } setDone(true); }; return <><PageHero eyebrow="BESPOKE DESIGN / سفارش اختصاصی" title={<>ایده شما،<br/><em>امضای ما.</em></>} desc="از یک اسکچ ساده تا فایل آماده ساخت، درخواست طراحی اختصاصی خود را در چند قدم ثبت کنید." icon={<WandSparkles size={100} strokeWidth={.5}/>}/><div className="container content-section"><div className="wizard-layout"><div><span className="eyebrow">YOUR VISION, OUR CRAFT</span><h2 className="detail-title">داستان قطعه‌تان را برای ما بگویید.</h2><p className="detail-intro">فرم زیر برای برآورد اولیه است. تیم آتلیه پس از بررسی جزئیات با شما هماهنگ می‌کند.</p><div className="wizard-steps">{['الهام‌بخش','نوع قطعه','جزئیات فنی','ارسال درخواست'].map((s,i) => <button key={s} className={step === i+1 ? 'current' : step > i+1 ? 'complete' : ''} onClick={() => setStep(i+1)}><span>{step > i+1 ? <Check size={16}/> : faNumber(i+1)}</span>{s}</button>)}</div>{done ? <div className="wizard-panel success-panel"><div className="success-icon"><Check size={32}/></div><h3>درخواست شما ثبت شد</h3><p>این یک نسخه نمایشی است؛ درخواست به سرور ارسال نشده است. برای ثبت واقعی، اتصال فرم به سرویس سفارشات لازم است.</p><button className="btn btn-outline" onClick={() => { setDone(false); setStep(1); }}>ثبت درخواست دیگر</button></div> : <div className="wizard-panel">{step === 1 && <><h3>چه چیزی در ذهن دارید؟</h3><p>اسکچ، تصویر الهام‌بخش یا مودبورد خود را اینجا اضافه کنید.</p><label className="upload-box"><UploadCloud size={30}/><strong>{fileName || 'برای انتخاب فایل کلیک کنید'}</strong><small>تصویر یا PDF، حداکثر ۱۰ مگابایت</small><input type="file" accept="image/*,.pdf" onChange={e => { const f = e.target.files?.[0]; if (f && f.size > 10 * 1024 * 1024) { onToast('حجم فایل باید کمتر از ۱۰ مگابایت باشد'); e.target.value = ''; return; } setFileName(f?.name || ''); }}/></label><label className="field-label">توضیح کوتاه ایده<textarea placeholder="حال و هوا، سبک مورد علاقه یا جزئیات مهم را بنویسید..." rows={4}/></label></>}{step === 2 && <><h3>چه قطعه‌ای طراحی کنیم؟</h3><p>نزدیک‌ترین دسته به ایده‌تان را انتخاب کنید.</p><div className="option-grid">{['انگشتر تک‌نگین','سرویس عروس','مدال اسلیمی','النگو فیوژن'].map((x,i) => <button className={category === x ? 'chosen' : ''} key={x} onClick={() => setCategory(x)}><span>{['◇','✧','✦','○'][i]}</span>{x}<Check size={17}/></button>)}</div></>}{step === 3 && <><h3>جزئیات فنی پروژه</h3><p>این اطلاعات به برآورد دقیق‌تر زمان و هزینه کمک می‌کند.</p><div className="form-grid"><label className="field-label">بودجه وزنی طلا (گرم)<input type="text" inputMode="decimal" value={weight} onChange={e => setWeight(e.target.value)} placeholder="مثلاً ۵ تا ۷ گرم"/></label><label className="field-label">نوع مخراجی<select value={setting} onChange={e => setSetting(e.target.value)}><option>چنگی</option><option>ریلی</option><option>پاوه</option><option>بدون نگین</option></select></label><label className="field-label">شیوه تولید<select value={quantity} onChange={e => setQuantity(e.target.value)}><option>تک‌سازی</option><option>تیراژ محدود</option><option>تولید انبوه</option></select></label></div></>}{step === 4 && <><h3>آخرین قدم، آغاز یک همکاری</h3><p>اطلاعات تماس را وارد کنید تا برای بررسی اولیه با شما هماهنگ شود.</p><div className="form-grid"><label className="field-label">نام و نام خانوادگی<input value={name} onChange={e => setName(e.target.value)} placeholder="نام شما"/></label><label className="field-label">شماره موبایل<input dir="ltr" inputMode="tel" value={phone} onChange={e => setPhone(e.target.value)} placeholder="09123456789"/></label></div><label className="checkbox-line"><input type="checkbox" checked={agree} onChange={e => setAgree(e.target.checked)}/><span>شرایط محرمانگی طرح و تماس برای بررسی سفارش را می‌پذیرم.</span></label><div className="nda-note"><ShieldCheck size={22}/><span><b>تعهد محرمانگی طرح</b> — فایل‌ها و ایده‌های شما فقط برای بررسی سفارش استفاده می‌شوند.</span></div></>}<div className="wizard-actions">{step > 1 && <button className="btn btn-outline" onClick={() => setStep(step-1)}>مرحله قبل</button>}<button className="btn btn-gold" onClick={() => step < 4 ? setStep(step+1) : submit()}>{step < 4 ? 'ادامه' : 'ثبت درخواست برآورد'} <ArrowLeft size={17}/></button></div></div>}</div><aside className="wizard-aside"><div className="aside-art"><JewelryVisual variant="ring" large/></div><div><span className="eyebrow">ATELIER PROCESS</span><h3>از الهام تا ساخت</h3><p>گفت‌وگو و بررسی نیاز → طراحی اولیه → بازبینی فنی → تحویل فایل آماده تولید</p><div className="aside-divider"/><span><ShieldCheck size={19}/> حفظ محرمانگی ایده</span><span><Gem size={19}/> طراحی با نگاه صنعتی</span><span><MessageCircle size={19}/> ارتباط مستقیم با آتلیه</span></div></aside></div></div></>; }

function ReaderProgress() { const [percent, setPercent] = useState(0); const [active, setActive] = useState(false); useEffect(() => { const update = () => { setActive(!!new URLSearchParams(window.location.search).get('article')); const reader = document.querySelector('.reader'); if (!reader) return; const rect = reader.getBoundingClientRect(); const total = reader.scrollHeight - window.innerHeight / 2; setPercent(Math.max(0, Math.min(100, ((-rect.top + window.innerHeight / 3) / Math.max(1, total)) * 100))); }; window.addEventListener('scroll', update, { passive: true }); const observer = new MutationObserver(update); observer.observe(document.body, { childList: true, subtree: true }); update(); return () => { window.removeEventListener('scroll', update); observer.disconnect(); }; }, []); return active ? <div className="reading-progress" style={{ width: `${percent}%` }} role="progressbar" aria-label="پیشرفت مطالعه" aria-valuenow={Math.round(percent)} aria-valuemin={0} aria-valuemax={100}/> : null; }
function JournalPage() { const [chosen, setChosen] = useState<string | null>(null); useEffect(() => { setChosen(new URLSearchParams(window.location.search).get('article')); }, []); const article = articles.find(a => a.id === chosen); return <><PageHero eyebrow="THE JOURNAL / مجله" title={<>فکر کنید. طراحی کنید.<br/><em>عمیق‌تر ببینید.</em></>} desc="دانش فنی، روایت‌های آتلیه و نگاه تازه به آینده طراحی جواهر." icon={<BookOpen size={100} strokeWidth={.5}/>}/><div className="container content-section">{article ? <><button className="back-link" onClick={() => { setChosen(null); window.history.replaceState({}, '', '/journal'); }}><ChevronRight size={17}/> بازگشت به مجله</button><div className="reader-layout"><article className="reader"><span className="eyebrow">{article.category} / {article.read}</span><h2>{article.title}</h2><div className="reader-meta"><span>یاسین • آتلیه یاسین گلد آرت</span><span>{article.date}</span></div><div className={`reader-image image-${article.image}`}><JewelryVisual variant={article.image} large/></div><p className="lead">{article.excerpt}</p><h3 id="insight">از ایده تا واقعیت کارگاه</h3><p>در طراحی طلا و جواهر، زیبایی فرم تنها نقطه شروع است. هر تصمیم در مدل‌سازی باید با محدودیت‌های متریال، چاپ و ریخته‌گری هماهنگ شود. یک فایل دقیق، زبان مشترک طراح و کارگاه است.</p><p>پیش از نهایی کردن طرح، ضخامت دیواره‌ها، موقعیت نگین‌ها و مسیر پرداخت را بررسی کنید. ثبت این جزئیات از رفت‌وبرگشت‌های پرهزینه در مراحل بعد جلوگیری می‌کند.</p><h3 id="practice">تمرین کاربردی</h3><p>یکی از طرح‌های قدیمی خود را باز کنید و آن را از نگاه سازنده بررسی کنید: آیا قطعه به‌سادگی از قالب خارج می‌شود؟ آیا جایگاه نگین دسترسی کافی برای مخراجی دارد؟ این پرسش‌های کوچک، کیفیت خروجی را تغییر می‌دهند.</p><div className="reader-author"><div className="avatar">ی</div><div><strong>یاسین</strong><p>طراح و مدرس طراحی سه‌بعدی طلا و جواهر</p></div></div></article><aside className="reader-aside"><div className="toc"><b>در این مقاله</b><a href="#insight">از ایده تا واقعیت کارگاه</a><a href="#practice">تمرین کاربردی</a></div><div className="template-card"><Download size={24}/><h4>چک‌لیست آماده‌سازی فایل</h4><p>نمونه محتوای دانلودی برای اعضای آکادمی</p><Link href="/auth">ورود برای دسترسی <ArrowUpLeft size={15}/></Link></div></aside></div></> : <><SectionHead eyebrow="LATEST STORIES" title={<>یادداشت‌های <em>آتلیه</em></>} desc="دانشی که بین میز طراحی و کارگاه جریان دارد."/><div className="article-grid all-articles">{articles.map(a => <div key={a.id} onClick={() => { setChosen(a.id); window.history.replaceState({}, '', `/journal?article=${a.id}`); window.scrollTo(0,0); }}><ArticleCard article={a}/></div>)}</div></>}</div></>; }

function AboutPage() { const [active, setActive] = useState(0); return <><PageHero eyebrow="OUR STORY / داستان ما" title={<>جایی که هنر،<br/><em>زبان صنعت را می‌آموزد.</em></>} desc="یاسین گلد آرت برای نزدیک کردن خلاقیت طراحان به واقعیت تولید شکل گرفته است." icon={<Gem size={100} strokeWidth={.5}/>}/><section className="section light-section"><div className="container about-grid"><div><span className="eyebrow">THE MANIFESTO</span><h2 className="detail-title">هر قطعه زیبا،<br/>شایسته ساختن است.</h2><p className="about-copy">ما باور داریم طراحی جواهر در نقطه تلاقی هنر، مهندسی و تجربه کارگاهی به بلوغ می‌رسد. آموزش در این آتلیه با مسئله‌های واقعی آغاز می‌شود و با فایلی که امکان تولید دارد معنا پیدا می‌کند.</p><p className="about-copy">هدف ما ساختن فضایی برای یادگیری، تجربه و همکاری میان طراح، هنرجو و سازنده است؛ فضایی که دقت فنی، هویت هنری را محدود نمی‌کند، بلکه به آن قدرت می‌دهد.</p><Link href="/contact" className="btn btn-dark">با ما در ارتباط باشید <ArrowUpLeft size={17}/></Link></div><div className="about-visual"><JewelryVisual variant="ring" large/><span>FORM MEETS FUNCTION</span></div></div></section><section className="section timeline-section"><div className="container"><SectionHead eyebrow="THE JOURNEY / مسیر آتلیه" title={<>تجربه‌ای در حال <em>ساخته شدن.</em></>} light/><div className="timeline">{[['۰۱','آغاز با طراحی','یادگیری زبان فرم و مدل‌سازی دقیق در محیط سه‌بعدی.'],['۰۲','پیوند با کارگاه','آزمودن ایده‌ها در کنار الزامات ساخت، چاپ و ریخته‌گری.'],['۰۳','آموزش چالش‌محور','تبدیل تجربه‌های فنی به مسیرهای یادگیری پروژه‌محور.'],['۰۴','آتلیه و مارکت‌پلیس','ایجاد بستری مشترک برای آموزش، فایل و سفارش اختصاصی.']].map(row => <div key={row[0]}><span>{row[0]}</span><h3>{row[1]}</h3><p>{row[2]}</p></div>)}</div></div></section><section className="section light-section"><div className="container"><SectionHead eyebrow="FROM CAD TO CRAFT" title={<>از مدل دیجیتال تا <em>جواهر واقعی.</em></>} desc="یک نگاه تعاملی به فرم‌هایی که با منطق ساخت طراحی می‌شوند."/><div className="showcase-layout"><JewelryVisual variant={['ring','band','pendant'][active]} large/><div><span className="eyebrow">DESIGN SHOWCASE / ۰{faNumber(active+1)}</span><h3>{['انگشتر تک‌نگین','رکاب ارگونومیک','مدال نقش‌پرداز'][active]}</h3><p>از تناسبات مدل سه‌بعدی تا جزئیات اجرایی، هر قطعه سفری میان ایده و ساخت را روایت می‌کند.</p><div className="showcase-tabs">{['انگشتر','رکاب','مدال'].map((x,i) => <button className={active===i?'on':''} key={x} onClick={() => setActive(i)}>{x}</button>)}</div></div></div></div></section></>; }

function ContactPage({ onToast }: { onToast: (s: string) => void }) { const [day, setDay] = useState<number | null>(null); const [time, setTime] = useState('۱۱:۰۰'); const [sent, setSent] = useState(false); const [name, setName] = useState(''); const [phone, setPhone] = useState(''); return <><PageHero eyebrow="LET'S TALK / ارتباط با ما" title={<>گفت‌وگو، آغاز<br/><em>یک همکاری زیباست.</em></>} desc="برای مشاوره، سفارش یا همکاری کارگاهی، از همین‌جا با آتلیه ارتباط بگیرید." icon={<MessageCircle size={100} strokeWidth={.5}/>}/><div className="container content-section"><SectionHead eyebrow="GET IN TOUCH" title={<>در کنار <em>شما هستیم.</em></>} desc="راه ارتباطی مناسب خود را انتخاب کنید."/><div className="contact-grid"><div className="contact-card"><MessageCircle/><small>VIP SUPPORT</small><h3>پشتیبانی واتساپ</h3><p>برای پرسش درباره دوره‌ها و سفارش‌ها</p><span>اطلاعات تماس به‌زودی</span></div><div className="contact-card"><Layers3/><small>COMMUNITY</small><h3>کانال تلگرام</h3><p>خبرهای آکادمی و نکات طراحی جواهر</p><span>اطلاعات کانال به‌زودی</span></div><div className="contact-card"><Mail/><small>EMAIL</small><h3>ایمیل مستقیم</h3><p>برای همکاری و مکاتبات رسمی</p><span>آدرس ایمیل به‌زودی</span></div><div className="contact-card"><MapPin/><small>THE ATELIER</small><h3>آتلیه در ایران</h3><p>جلسات حضوری با هماهنگی قبلی</p><span>آدرس پس از هماهنگی</span></div></div><div className="contact-split"><div className="booking-card"><span className="eyebrow">BOOK A CONSULTATION</span><h2>رزرو وقت مشاوره</h2><p>زمان پیشنهادی خود را انتخاب کنید. تقویم در نسخه نمایشی است.</p><div className="calendar-title"><CalendarDays size={20}/> انتخاب روز پیشنهادی</div><div className="calendar-days">{['ش','ی','د','س','چ','پ','ج'].map((d,i) => <span key={i}>{d}</span>)}{Array.from({length:14},(_,i) => <button className={day===i+1?'on':''} key={i} onClick={() => setDay(i+1)}>{faNumber(i+1)}</button>)}</div><div className="time-slots">{['۱۱:۰۰','۱۳:۰۰','۱۵:۰۰','۱۷:۰۰'].map(t => <button className={time===t?'on':''} key={t} onClick={() => setTime(t)}>{t}</button>)}</div><button className="btn btn-gold full" onClick={() => onToast(day ? `روز ${faNumber(day)}، ساعت ${time} انتخاب شد؛ رزرو واقعی در نسخه نمایشی فعال نیست` : 'ابتدا یک روز را انتخاب کنید')}>انتخاب زمان مشاوره <ArrowLeft size={17}/></button></div><div className="partner-card"><span className="eyebrow">WORKSHOP PARTNERSHIP</span><h2>دعوت به همکاری کارگاه‌ها</h2><p>اگر صاحب کارگاه ریخته‌گری یا تولیدی هستید، برای همکاری در پروژه‌ها و معرفی هنرجویان مستعد با ما ارتباط بگیرید.</p>{sent ? <div className="inline-success"><Check/> درخواست نمایشی ثبت شد. اتصال فرم به سرویس تماس برای دریافت واقعی لازم است.</div> : <div className="partner-form"><label className="field-label">نام کارگاه یا مجموعه<input value={name} onChange={e => setName(e.target.value)} placeholder="نام مجموعه"/></label><label className="field-label">شماره تماس<input value={phone} onChange={e => setPhone(e.target.value)} placeholder="۰۹۱۲..."/></label><label className="field-label">حوزه فعالیت<textarea rows={3} placeholder="زمینه همکاری مورد نظر..."/></label><button className="btn btn-outline full" onClick={() => name.trim() && phone.trim() ? setSent(true) : onToast('نام مجموعه و شماره تماس را وارد کنید')}>ارسال درخواست همکاری <ArrowUpLeft size={17}/></button></div>}</div></div></div></>; }

function ChallengesPage({ onAuth }: { onAuth: () => void }) { const [active, setActive] = useState(0); return <><PageHero eyebrow="DESIGN CHALLENGES / چالش‌ها" title={<>تمرین کنید.<br/><em>بهتر طراحی کنید.</em></>} desc="هر چالش، یک مسئله واقعی برای ساختن مهارت‌های دقیق‌تر و کارگاهی‌تر." icon={<Layers3 size={100} strokeWidth={.5}/>}/><div className="container content-section"><SectionHead eyebrow="PRACTICE WITH PURPOSE" title={<>چالش‌های <em>منتخب</em></>} desc="تمرین‌های نمونه برای آشنایی با مسیر یادگیری چالش‌محور."/><div className="challenge-grid">{[['طراحی رکاب سبک و مقاوم','ضخامت، وزن و استحکام را در یک مدل متعادل کنید.','مقدماتی'],['جای‌گذاری هالو بدون تداخل چنگ','نگین‌ها را با تلرانس مناسب در فرم هالو بنشانید.','پیشرفته'],['خروجی آماده چاپ یک مدال','مش، ابعاد و جزئیات را برای ساخت نهایی کنترل کنید.','پیشرفته']].map((c,i) => <div className={`challenge-card ${active===i?'active':''}`} key={i} onClick={() => setActive(i)}><span>چالش ۰{faNumber(i+1)} <small>{c[2]}</small></span><h3>{c[0]}</h3><p>{c[1]}</p><button onClick={e => { e.stopPropagation(); onAuth(); }}>شرکت در چالش <ArrowUpLeft size={16}/></button></div>)}</div></div></>; }
function ProfilePage({ user, cartCount, purchased, onAuth, onLogout }: { user: string | null; cartCount: number; purchased: string[]; onAuth: () => void; onLogout: () => void }) {
  return <><PageHero eyebrow="MY ATELIER / حساب من" title={<>فضای شخصی <em>شما.</em></>} desc="دوره‌ها، فایل‌ها و مسیر یادگیری شما در یک نقطه." icon={<UserRound size={100} strokeWidth={.5}/>}/><div className="container content-section profile-content">{user ? <><div className="profile-welcome"><div className="avatar">{user.slice(0,1)}</div><div><span>خوش آمدید</span><h2>{user}</h2></div><button onClick={onLogout}>خروج از حساب</button></div><div className="profile-stats"><div><BookOpen/><strong>۰</strong><span>دوره‌های من</span></div><div><Download/><strong>{faNumber(purchased.length)}</strong><span>فایل‌های خرید نمایشی</span></div><div><ShoppingBag/><strong>{faNumber(cartCount)}</strong><span>محصول در سبد خرید</span></div></div>{purchased.length > 0 && <div className="download-list"><h3>فایل‌های من</h3><p>نسخه نمایشی هر مورد یک مدل ساده نمونه است و برای تولید کاربرد ندارد.</p>{purchased.map(id => { const product = products.find(p => p.id === id); return product && <div key={id}><span><FileBox size={18}/>{product.title}</span><a href="/sample-ring.stl" download={`${product.en.toLowerCase().replaceAll(' ', '-')}-demo.stl`}>دانلود نمونه STL <Download size={16}/></a></div>; })}</div>}<p className="profile-hint">حساب و خریدهای نمایشی فقط به‌صورت محلی روی همین مرورگر ذخیره می‌شوند.</p></> : <div className="profile-empty"><UserRound size={42}/><h2>به فضای شخصی خود وارد شوید</h2><p>برای مشاهده دوره‌ها، فایل‌های خریداری شده و پیگیری مسیرتان وارد شوید.</p><button className="btn btn-gold" onClick={onAuth}>ورود / ثبت‌نام <ArrowUpLeft size={17}/></button></div>}</div></>;
}
function AuthPage({ onLogin }: { onLogin: (s: string) => void }) { return <div className="auth-page"><div className="container"><AuthForm onLogin={onLogin}/></div></div>; }

function AuthForm({ onLogin }: { onLogin: (s: string) => void }) { const [role, setRole] = useState<'student'|'workshop'>('student'); const [method, setMethod] = useState<'otp'|'password'>('otp'); const [stage, setStage] = useState<'form'|'verify'>('form'); const [phone, setPhone] = useState(''); const [code, setCode] = useState(''); const [password, setPassword] = useState(''); const [goal, setGoal] = useState('یادگیری مهارت'); const [error, setError] = useState(''); const normalized = phone.replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))); const valid = /^09\d{9}$/.test(normalized); const submit = () => { if (!valid) { setError('شماره موبایل معتبر وارد کنید.'); return; } if (method === 'password' && !password) { setError('رمز عبور را وارد کنید.'); return; } setError(''); if (method === 'otp' && stage === 'form') { setStage('verify'); return; } if (method === 'otp' && code.length < 4) { setError('کد چهار رقمی نمایشی را وارد کنید.'); return; } onLogin(role === 'workshop' ? 'همکار کارگاه' : 'هنرجوی آتلیه'); }; return <div className="auth-form"><div className="auth-brand"><span className="brand-mark"><Gem size={24}/></span><span>YASIN GOLD ART</span></div><span className="eyebrow">WELCOME TO THE ATELIER</span><h2>به دنیای طراحی <em>خوش آمدید.</em></h2><p>برای ادامه، نقش خود را انتخاب کنید.</p><div className="auth-tabs"><button className={role==='student'?'on':''} onClick={() => setRole('student')}>هنرجو و خریدار</button><button className={role==='workshop'?'on':''} onClick={() => setRole('workshop')}>کارگاه و سازنده</button></div><div className="auth-method"><button className={method==='otp'?'on':''} onClick={() => { setMethod('otp'); setStage('form'); }}>ورود با کد تایید</button><button className={method==='password'?'on':''} onClick={() => { setMethod('password'); setStage('form'); }}>ورود با رمز عبور</button></div><label className="field-label">شماره موبایل<input dir="ltr" type="tel" inputMode="tel" value={phone} onChange={e => setPhone(e.target.value)} placeholder="09123456789"/></label>{method === 'password' ? <label className="field-label">رمز عبور<input dir="ltr" type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="••••••••"/></label> : stage === 'verify' && <label className="field-label">کد تایید نمایشی<input dir="ltr" inputMode="numeric" maxLength={6} value={code} onChange={e => setCode(e.target.value)} placeholder="1234"/><small>هر کد ۴ رقمی برای ورود نمایشی پذیرفته می‌شود.</small></label>}<span className="goal-label">هدف شما از پیوستن چیست؟</span><div className="goal-options">{['یادگیری مهارت','خرید فایل سه‌بعدی','سفارش پروژه اختصاصی'].map(x => <button className={goal===x?'on':''} key={x} onClick={() => setGoal(x)}>{x}</button>)}</div>{error && <div className="form-error">{error}</div>}<button className="btn btn-gold full" onClick={submit}>{stage === 'form' && method === 'otp' ? 'دریافت کد تایید' : 'ورود به آتلیه'} <ArrowLeft size={17}/></button><div className="social-placeholder"><span>یا ادامه از طریق</span><button onClick={() => setError('ورود اجتماعی در نسخه نمایشی فعال نیست.')}>G &nbsp; حساب گوگل</button></div><small className="auth-disclaimer">ورود در این نمونه نمایشی است و کد پیامکی واقعی ارسال نمی‌شود.</small></div>; }

function SearchPanel({ close }: { close: () => void }) { const [query, setQuery] = useState(''); const results = [...courses.map(c => ({ title: c.title, type: 'دوره', href: `/courses?course=${c.id}` })), ...products.map(p => ({ title: p.title, type: 'فایل', href: '/marketplace' })), ...articles.map(a => ({ title: a.title, type: 'مقاله', href: `/journal?article=${a.id}` }))].filter(x => x.title.includes(query)).slice(0,6); return <div className="search-panel"><span className="eyebrow">SEARCH YASIN GOLD ART</span><h2>دنبال چه می‌گردید؟</h2><label><Search size={21}/><input autoFocus placeholder="دوره، فایل یا مقاله را جستجو کنید..." value={query} onChange={e => setQuery(e.target.value)}/></label><div className="search-results">{results.map((r,i) => <Link href={r.href} onClick={close} key={i}><span>{r.type}</span>{r.title}<ArrowUpLeft size={16}/></Link>)}{!results.length && <p>نتیجه‌ای پیدا نشد. عبارت دیگری امتحان کنید.</p>}</div></div>; }
function PreviewPanel({ product, onAdd }: { product: Product; onAdd: () => void }) { const [wire, setWire] = useState(false); return <div className="preview-panel"><div className={`preview-image ${wire?'wireframe':''}`}><JewelryVisual variant={product.image} large/><button onClick={() => setWire(!wire)}><Eye size={16}/>{wire ? 'نمای رندر' : 'نمای وایرفریم'}</button></div><div className="preview-info"><span className="eyebrow">3D ASSET / {product.en}</span><h2>{product.title}</h2><p>مدل سه‌بعدی پایه با جزئیات فنی برای ویرایش و آماده‌سازی در مسیر تولید.</p><div className="preview-specs"><div><span>فرمت فایل</span><strong>{product.format.map(x => `.${x}`).join(' / ')}</strong></div><div><span>وزن تقریبی طلای ۷۵۰</span><strong>{product.weight}</strong></div><div><span>مشخصات نگین</span><strong>{product.stones}</strong></div><div><span>تغییر سایز</span><strong>{product.resize}</strong></div></div><div className="preview-bottom"><strong>{money(product.price)}</strong><button className="btn btn-gold" onClick={onAdd}>افزودن به سبد <Plus size={18}/></button></div><small>مقادیر فنی نمونه‌اند و باید پیش از تولید روی مدل نهایی بررسی شوند.</small></div></div>; }
function EmptyState() { return <div className="empty-state"><Search size={30}/><h3>موردی پیدا نشد</h3><p>فیلترها را تغییر دهید و دوباره امتحان کنید.</p></div>; }
function Footer() { return <footer className="footer"><div className="container footer-main"><div className="footer-brand"><Brand/><p>خانه‌ای برای یادگیری، طراحی و ساخت جواهراتی که با فکر و دقت خلق می‌شوند.</p><div className="footer-social"><span aria-label="اینستاگرام، به‌زودی"><Instagram size={18}/></span><span aria-label="تلگرام، به‌زودی"><MessageCircle size={18}/></span><span aria-label="ایمیل، به‌زودی"><Mail size={18}/></span></div></div><div><h4>کاوش کنید</h4><Link href="/courses">دوره‌ها و پکیج‌ها</Link><Link href="/marketplace">مارکت‌پلیس فایل‌ها</Link><Link href="/orders">سفارش طراحی اختصاصی</Link><Link href="/challenges">چالش‌های طراحی</Link></div><div><h4>یاسین گلد آرت</h4><Link href="/about">درباره آتلیه</Link><Link href="/journal">مجله تخصصی</Link><Link href="/contact">ارتباط با ما</Link><Link href="/contact">همکاری کارگاهی</Link></div><div className="footer-news"><h4>نامه‌ای از آتلیه</h4><p>یادداشت‌های طراحی و خبرهای آکادمی، به‌زودی.</p><div className="newsletter-mock"><Mail size={17}/><span>خبرنامه به‌زودی فعال می‌شود</span></div></div></div><div className="container footer-bottom"><span>© {faNumber(2026)} Yasin Gold Art. تمامی حقوق محفوظ است.</span><span>طراحی شده برای خلق فردا ✦</span></div></footer>; }
